<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../admin/includes/auth.php';
$id=(int)($_GET['id']??$_POST['id']??0);$errors=[];$project=['title'=>'','slug'=>'','category'=>'','short_description'=>'','challenge'=>'','solution'=>'','technologies'=>'','image'=>'','live_url'=>'','github_url'=>'','is_featured'=>0,'is_published'=>1];
if($id){$stmt=db()->prepare('SELECT * FROM projects WHERE id=?');$stmt->execute([$id]);$found=$stmt->fetch();if($found)$project=array_merge($project,array_map(static fn($v)=>$v??'',$found));}
if($_SERVER['REQUEST_METHOD']==='POST'){foreach(array_keys($project) as $key){if(isset($_POST[$key]))$project[$key]=is_string($_POST[$key])?trim($_POST[$key]):$_POST[$key];}$project['is_featured']=isset($_POST['is_featured'])?1:0;$project['is_published']=isset($_POST['is_published'])?1:0;if($project['title']===''||$project['category']===''||$project['short_description']==='')$errors[]='Title, category and short description are required.';if($project['slug']==='')$project['slug']=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$project['title']),'-'));if(!$errors){if($id){db()->prepare('UPDATE projects SET title=?,slug=?,category=?,short_description=?,challenge=?,solution=?,technologies=?,image=?,live_url=?,github_url=?,is_featured=?,is_published=? WHERE id=?')->execute([$project['title'],$project['slug'],$project['category'],$project['short_description'],$project['challenge'],$project['solution'],$project['technologies'],$project['image'],$project['live_url'],$project['github_url'],$project['is_featured'],$project['is_published'],$id]);}else{db()->prepare('INSERT INTO projects(title,slug,category,short_description,challenge,solution,technologies,image,live_url,github_url,is_featured,is_published) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$project['title'],$project['slug'],$project['category'],$project['short_description'],$project['challenge'],$project['solution'],$project['technologies'],$project['image'],$project['live_url'],$project['github_url'],$project['is_featured'],$project['is_published']]);}header('Location: projects.php');exit;}}
$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $id?'Edit':'Add' ?> Project</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:1000px"><div class="d-flex justify-content-between mb-4"><h1 class="h2"><?= $id?'Edit':'Add' ?> Project</h1><a href="projects.php" class="btn btn-outline-secondary">Back</a></div><?php foreach($errors as $e):?><div class="alert alert-danger"><?=$esc($e)?></div><?php endforeach;?><form method="post" class="card border-0 shadow-sm p-4"><input type="hidden" name="id" value="<?=$id?>"><div class="row g-3"><div class="col-md-8"><label class="form-label">Title</label><input name="title" class="form-control" value="<?=$esc($project['title'])?>" required></div><div class="col-md-4"><label class="form-label">Category</label><input name="category" class="form-control" value="<?=$esc($project['category'])?>" required></div><div class="col-md-8"><label class="form-label">Slug</label><input name="slug" class="form-control" value="<?=$esc($project['slug'])?>"></div><div class="col-12"><label class="form-label">Short Description</label><textarea name="short_description" class="form-control" rows="3" required><?=$esc($project['short_description'])?></textarea></div><div class="col-md-6"><label class="form-label">Challenge</label><textarea name="challenge" class="form-control" rows="5"><?=$esc($project['challenge'])?></textarea></div><div class="col-md-6"><label class="form-label">Solution</label><textarea name="solution" class="form-control" rows="5"><?=$esc($project['solution'])?></textarea></div><div class="col-12"><label class="form-label">Technologies</label><input name="technologies" class="form-control" value="<?=$esc($project['technologies'])?>"></div><div class="col-md-6"><label class="form-label">Image URL / Path</label><input name="image" class="form-control" value="<?=$esc($project['image'])?>"></div><div class="col-md-3"><label class="form-label">Live URL</label><input name="live_url" class="form-control" value="<?=$esc($project['live_url'])?>"></div><div class="col-md-3"><label class="form-label">GitHub URL</label><input name="github_url" class="form-control" value="<?=$esc($project['github_url'])?>"></div><div class="col-12 d-flex gap-4"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_featured" id="featured" <?=((int)($project['is_featured']??0)?'checked':'')?>><label class="form-check-label" for="featured">Featured project</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="is_published" id="published" <?=((int)($project['is_published']??0)?'checked':'')?>><label class="form-check-label" for="published">Published</label></div></div><div class="col-12"><button class="btn btn-primary">Save Project</button></div></div></form></main></body></html>